source .venv/bin/activate && python3 << 'EOF'
import json
ids=["2112.03333","2405.16331","2301.08994","1506.08292","2503.01509","2203.15897",
"2511.22535","0910.5060","2505.20313","2507.09751","2304.06333","2402.04249",
"2512.20677","2602.05656","2605.23989","2110.14297","2002.05217","2401.16656"]
db={}
for f in ['/tmp/arxiv_scored.json','/tmp/supp.json']:
    try:
        for p in json.load(open(f)):
            db.setdefault(p['id'],p)
    except: pass
out={}
for i in ids:
    p=db.get(i,{})
    out[i]={'title':p.get('title',''),'year':p.get('year',''),
            'authors':p.get('authors',[]),'summary':p.get('summary','')}
json.dump(out,open('/tmp/abstracts.json','w'),indent=2)
for i in ids:
    p=out[i]
    print(f"\n### [{i}] ({p['year']}) {p['title']}")
    print(f"Authors: {', '.join(p['authors'][:5]) if p['authors'] else 'N/A'}")
    print(f"Abstract: {p['summary'][:700]}")
EOF

